const pages = [...document.querySelectorAll('.page')];
const nav = [...document.querySelectorAll('.navbtn')];

const slideData = {
  Cardiovascular: {
    title: 'Cardiovascular – Heart Muscle',
    sub: 'Cardiovascular System › Heart › Myocardium',
    image: 'data:image/jpeg;base64,',
    badge: 'CARDIOVASCULAR',
    see: 'Bundles of cardiac muscle viewed at low magnification. The section demonstrates the thick muscular wall of the heart and the organization of myocardial tissue.',
    means: 'Cardiac muscle is specialized for continuous, coordinated contraction. Cardiomyocytes are organized into bundles that generate the force needed to pump blood.',
    matters: 'Recognizing myocardium helps connect cardiac structure with function and provides a foundation for identifying cardiac pathology.',
    clinical: ['Myocardial infarction','Cardiomyopathy','Myocarditis']
  },
  Respiratory: {
    title: 'Lung – Respiratory Tissue',
    sub: 'Respiratory System › Lung › Histology Slides',
    image: 'data:image/jpeg;base64,',
    badge: 'RESPIRATORY',
    see: 'Delicate lung tissue contains extensive air spaces, thin alveolar walls, blood vessels, and conducting airways.',
    means: 'The architecture of the lung creates a large surface area for gas exchange while maintaining close contact between air spaces and capillary blood.',
    matters: 'Recognizing normal lung architecture provides a baseline for understanding respiratory disease and pathology.',
    clinical: ['Emphysema','Pulmonary fibrosis','ARDS']
  }
};

const lungSlides = [
  {src:'data:image/jpeg;base64,', label:'Respiratory image 1'},
  {src:'data:image/jpeg;base64,', label:'Respiratory image 2'},
  {src:'data:image/jpeg;base64,', label:'Respiratory image 3'}
];
let currentLungIndex = 0;
let labelled = false;

function showPage(id) {
  // "Slide Box" in the navigation is the tissue/system selector.
  pages.forEach(p => p.classList.toggle('active', p.id === id));
  nav.forEach(n => n.classList.toggle('active', n.dataset.page === id));
  window.scrollTo({top:0, behavior:'smooth'});
  if (id === 'slidebox') setTimeout(resetViewer, 20);
}

const systemCards = [...document.querySelectorAll('.system[data-system]')];
const slideSearch = document.getElementById('slideSearch');
const systemFilter = document.getElementById('systemFilter');
const slideResultCount = document.getElementById('slideResultCount');
const clearSlideFilters = document.getElementById('clearSlideFilters');

function updateSystemSearch() {
  const q = (slideSearch?.value || '').trim().toLowerCase();
  const filter = systemFilter?.value || 'All';
  let visible = 0;
  systemCards.forEach(card => {
    const name = (card.dataset.system || '').toLowerCase();
    const matchesText = !q || name.includes(q) || card.textContent.toLowerCase().includes(q);
    const matchesFilter = filter === 'All' || card.dataset.system === filter;
    const show = matchesText && matchesFilter;
    card.classList.toggle('is-hidden', !show);
    if (show) visible += 1;
  });
  if (slideResultCount) slideResultCount.textContent = visible + (visible === 1 ? ' system' : ' systems');
  const notice = document.getElementById('systemNotice');
  if (notice && visible === 0) notice.textContent = 'No matching tissue or organ systems found. Try another search or clear the filters.';
  else if (notice && notice.textContent.startsWith('No matching tissue')) notice.textContent = '';
}

slideSearch?.addEventListener('input', updateSystemSearch);
systemFilter?.addEventListener('change', updateSystemSearch);
clearSlideFilters?.addEventListener('click', () => {
  if (slideSearch) slideSearch.value = '';
  if (systemFilter) systemFilter.value = 'All';
  updateSystemSearch();
  slideSearch?.focus();
});
updateSystemSearch();

window.openSystem = function openSystem(key) {
  const notice = document.getElementById('systemNotice');
  if (notice) notice.textContent = '';

  if (key === 'Cardiovascular') {
    loadSlide('Cardiovascular');
    showPage('slidebox');
  } else if (key === 'Respiratory') {
    currentLungIndex = 0;
    loadSlide('Respiratory');
    showPage('slidebox');
  } else if (key === 'All Slides') {
    showPage('slidebox');
  } else {
    showPage('tissues');
    if (notice) notice.textContent = key + ' slides will be added to this system soon.';
  }
}

nav.forEach(btn => {
  btn.addEventListener('click', () => {
    const target = btn.dataset.page;
    if (location.hash !== '#' + target) location.hash = target; else showPage(target);
  });
});

// Home cards and all system cards are real click targets.
document.querySelectorAll('[data-go]').forEach(el => {
  el.addEventListener('click', () => showPage(el.dataset.go));
});
document.querySelectorAll('.system[data-system]').forEach(card => {
  card.addEventListener('click', () => openSystem(card.dataset.system));
});

function loadSlide(key) {
  const d = slideData[key];
  if (!d) return;

  document.getElementById('slideTitle').textContent = d.title;
  document.getElementById('slideSub').textContent = d.sub;
  document.getElementById('crumb').textContent = '← Back to ' + key + ' System';
  document.getElementById('systemBadge').textContent = d.badge;
  document.getElementById('whatSee').textContent = d.see;
  document.getElementById('whatMeans').textContent = d.means;
  document.getElementById('whyMatters').textContent = d.matters;
  document.getElementById('clinical').innerHTML = d.clinical.map(x => '<li>'+x+'</li>').join('');
  const metadata = document.getElementById('slideMetadata');
  if (metadata) {
    metadata.innerHTML = '<span><b>System</b>' + key + '</span><span><b>Slide</b>' + d.title + '</span><span><b>Viewer</b>Interactive</span>';
  }
  setViewerStatus('Loading slide…');

  const image = document.getElementById('slideImage');
  const thumbs = document.querySelector('.thumb-stack');
  const counter = document.getElementById('lungCounter');

  if (key === 'Respiratory') {
    thumbs.style.display = 'flex';
    image.src = lungSlides[currentLungIndex].src;
    image.alt = lungSlides[currentLungIndex].label;
    document.querySelectorAll('[data-lung-index]').forEach((b,i) =>
      b.classList.toggle('active', i === currentLungIndex)
    );
    counter.style.display = 'block';
    counter.textContent = `Lung image ${currentLungIndex+1} of ${lungSlides.length}`;
  } else {
    thumbs.style.display = 'none';
    counter.style.display = 'none';
    image.src = d.image;
    image.alt = d.title;
  }

  // Update labelled-view text depending on the current system.
  const labels = key === 'Respiratory'
    ? [
        ['c1','Alveolar space','alveolar'],
        ['c2','Type II pneumocyte','pneumocyte'],
        ['c3','Capillary','capillary']
      ]
    : [
        ['c1','Myocardium','myocardium'],
        ['c2','Cardiac muscle bundles','cardiac'],
        ['c3','Connective tissue septum','septum']
      ];

  labels.forEach(([cls,text,labelKey]) => {
    const el = document.querySelector('.'+cls);
    if (el) {
      el.innerHTML = '<span></span>' + text;
      el.dataset.label = labelKey;
    }
  });

  setLabelled(false);
  setActiveTab('info');
  setTimeout(resetViewer, 30);
}

document.querySelectorAll('[data-lung-index]').forEach(btn => {
  btn.addEventListener('click', e => {
    e.stopPropagation();
    currentLungIndex = Number(btn.dataset.lungIndex);
    document.getElementById('slideImage').src = lungSlides[currentLungIndex].src;
    document.getElementById('slideImage').alt = lungSlides[currentLungIndex].label;
    document.querySelectorAll('[data-lung-index]').forEach((b,i) =>
      b.classList.toggle('active', i === currentLungIndex)
    );
    document.getElementById('lungCounter').textContent =
      `Lung image ${currentLungIndex+1} of ${lungSlides.length}`;
    setLabelled(false);
    resetViewer();
  });
});

// Back button returns to the tissue selector, which is now the Slide Box navigation page.
document.getElementById('crumb').addEventListener('click', () => showPage('tissues'));

// Viewer controls.
const viewer = document.getElementById('viewer');
const img = document.getElementById('slideImage');
const pct = document.getElementById('pct');
const mag = document.getElementById('mag');
let zoom = 1, x = 0, y = 0, drag = false, sx = 0, sy = 0;

function fitSize() {
  const ar = img.naturalWidth / img.naturalHeight;
  const vr = viewer.clientWidth / viewer.clientHeight;
  if (ar > vr) {
    img.style.width = viewer.clientWidth + 'px';
    img.style.height = 'auto';
  } else {
    img.style.height = viewer.clientHeight + 'px';
    img.style.width = 'auto';
  }
}
function render() {
  img.style.transform =
    `translate(calc(-50% + ${x}px),calc(-50% + ${y}px)) scale(${zoom})`;
  const z = Math.round(zoom*100) + '%';
  pct.textContent = z;
  mag.textContent = z;
}
function resetViewer() {
  zoom = 1; x = 0; y = 0;
  if (img.complete) fitSize();
  render();
}
img.addEventListener('load', () => { setViewerStatus(''); resetViewer(); });
img.addEventListener('error', () => setViewerStatus('Unable to load this slide image. Try Reset View or choose another slide.', 'error'));
function setViewerStatus(message, type='') {
  const status = document.getElementById('viewerStatus');
  if (!status) return;
  status.textContent = message;
  status.className = 'viewer-status' + (type ? ' ' + type : '');
  status.hidden = !message;
}
setViewerStatus('Loading slide…');

function changeZoom(f, px=viewer.clientWidth/2, py=viewer.clientHeight/2) {
  const old = zoom;
  zoom = Math.max(1, Math.min(8, zoom*f));
  const r = viewer.getBoundingClientRect();
  const cx = px-r.width/2, cy = py-r.height/2;
  if (old !== zoom) {
    x = (x-cx)*(zoom/old)+cx;
    y = (y-cy)*(zoom/old)+cy;
  }
  render();
}
document.getElementById('plus').addEventListener('click', () => changeZoom(1.35));
document.getElementById('minus').addEventListener('click', () => changeZoom(1/1.35));
document.getElementById('reset').addEventListener('click', resetViewer);
document.getElementById('full').addEventListener('click', () => {
  if (viewer.requestFullscreen) viewer.requestFullscreen();
});
viewer.addEventListener('wheel', e => {
  e.preventDefault();
  const r = viewer.getBoundingClientRect();
  changeZoom(e.deltaY < 0 ? 1.16 : 1/1.16, e.clientX-r.left, e.clientY-r.top);
}, {passive:false});
viewer.addEventListener('dblclick', e => {
  const r = viewer.getBoundingClientRect();
  changeZoom(zoom > 3 ? 1/zoom : 1.7, e.clientX-r.left, e.clientY-r.top);
});
viewer.addEventListener('pointerdown', e => {
  if (zoom <= 1) return;
  drag = true; sx = e.clientX-x; sy = e.clientY-y;
  viewer.classList.add('dragging');
  viewer.setPointerCapture(e.pointerId);
});
viewer.addEventListener('pointermove', e => {
  if (!drag) return;
  x = e.clientX-sx; y = e.clientY-sy; render();
});
['pointerup','pointercancel','pointerleave'].forEach(evt =>
  viewer.addEventListener(evt, () => {
    drag=false; viewer.classList.remove('dragging');
  })
);
window.addEventListener('resize', resetViewer);

// Labelled / unlabelled.
function setLabelled(on) {
  labelled = on;
  const overlay = document.getElementById('labelOverlay');
  overlay.classList.toggle('show', on);
  overlay.setAttribute('aria-hidden', String(!on));
  document.getElementById('unlabelledBtn').classList.toggle('active', !on);
  document.getElementById('labelledBtn').classList.toggle('active', on);
  document.querySelectorAll('.callout').forEach(c => c.classList.remove('active'));
  document.getElementById('labelInfo').innerHTML = on
    ? '<b>Click a label</b><span>Select a labelled structure to learn more.</span>'
    : '<b>Unlabelled view</b><span>Try identifying the structures yourself before revealing the labels.</span>';
}
document.getElementById('unlabelledBtn').addEventListener('click', () => setLabelled(false));
document.getElementById('labelledBtn').addEventListener('click', () => setLabelled(true));

const labelDetails = {
  myocardium:['Myocardium','The thick muscular layer of the heart wall.'],
  cardiac:['Cardiac muscle bundles','Organized cardiac muscle fibres that generate coordinated contraction.'],
  septum:['Connective tissue septum','Connective tissue that separates and supports groups of muscle fibres.'],
  alveolar:['Alveolar space','Open air spaces where gas exchange occurs.'],
  pneumocyte:['Type II pneumocyte','A specialized alveolar cell that produces pulmonary surfactant.'],
  capillary:['Capillary','Small blood vessels within the alveolar septa where gases move between blood and air.']
};
document.querySelectorAll('.callout').forEach(btn => {
  btn.addEventListener('click', () => {
    const d = labelDetails[btn.dataset.label];
    if (!d) return;
    document.querySelectorAll('.callout').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById('labelInfo').innerHTML =
      '<b>'+d[0]+'</b><span>'+d[1]+'</span>';
  });
});

// Sidebar tabs.
function setActiveTab(name) {
  document.querySelectorAll('.tab').forEach(t =>
    t.classList.toggle('active', t.dataset.tab === name)
  );
  document.getElementById('tabInfo').classList.toggle('active', name === 'info');
  document.getElementById('tabIdentify').classList.toggle('active', name === 'identify');
  document.getElementById('tabRelated').classList.toggle('active', name === 'related');
}
document.querySelectorAll('.tab').forEach(t =>
  t.addEventListener('click', () => setActiveTab(t.dataset.tab))
);
setActiveTab('info');

// Search.
document.getElementById('siteSearch').addEventListener('submit', e => {
  e.preventDefault();
  const q = document.getElementById('searchInput').value.trim().toLowerCase();
  if (!q) return;
  const slideMatch = Object.entries(slideData).find(([key, d]) => {
    const haystack = (key + ' ' + d.title + ' ' + d.sub).toLowerCase();
    return haystack.includes(q);
  });
  if (slideMatch) {
    const [key] = slideMatch;
    if (key === 'Cardiovascular') {
      loadSlide(key); showPage('slidebox'); return;
    }
    if (key === 'Respiratory') {
      currentLungIndex = 0; loadSlide(key); showPage('slidebox'); return;
    }
  }
  if (q.includes('quiz') || q.includes('practice')) { showPage('quiz'); return; }
  if (q.includes('how to') || q.includes('help')) { showPage('howto'); return; }
  if (q.includes('resource')) { showPage('resources'); return; }

  if (slideSearch) {
    slideSearch.value = q;
    showPage('tissues');
    updateSystemSearch();
  } else {
    showPage('tissues');
  }
});

// Top-right utilities.
document.getElementById('headerSearch')?.addEventListener('click', () => {
  showPage('home');
  const input = document.getElementById('searchInput');
  if (input) { input.focus(); input.scrollIntoView({behavior:'smooth',block:'center'}); }
});
document.getElementById('headerBookmark')?.addEventListener('click', () => showPage('tissues'));
document.getElementById('headerProfile')?.addEventListener('click', () => showPage('howto'));

// v17 tissue-specific quiz engine.
const quizSets={
 cardiovascular:{title:'Heart Muscle Quiz',badge:'CARDIOVASCULAR',image:'cardio_he.jpg',imageLabel:'H&E · Cardiovascular',questions:[
  {q:'Which tissue system is represented by this specimen?',options:['Cardiovascular','Respiratory','Renal / Urinary','Nervous'],correct:0,why:'This specimen shows myocardium, the cardiac muscle tissue of the heart.'},
  {q:'What type of muscle forms the myocardium?',options:['Skeletal muscle','Cardiac muscle','Smooth muscle','Dense connective tissue'],correct:1,why:'The myocardium is composed primarily of cardiac muscle.'},
  {q:'What is a major function of cardiac muscle?',options:['Voluntary movement','Coordinated contraction to pump blood','Gas exchange','Filtration of plasma'],correct:1,why:'Cardiac muscle contracts continuously and coordinately to generate the force that pumps blood.'},
  {q:'Which feature is characteristic of cardiomyocytes at higher magnification?',options:['Peripheral multinucleation only','Branching fibres and central nuclei','Cilia and goblet cells','Large cartilage plates'],correct:1,why:'Cardiomyocytes commonly show central nuclei, branching fibres, and intercalated discs.'}
 ]},
 respiratory:{title:'Lung Histology Quiz',badge:'RESPIRATORY',image:'lung_1_he.jpg',imageLabel:'H&E · Respiratory',questions:[
  {q:'What structure dominates this lung specimen?',options:['Alveoli','Renal corpuscles','Cardiac muscle bundles','Intestinal villi'],correct:0,why:'The numerous open air spaces are alveoli, the principal sites of pulmonary gas exchange.'},
  {q:'Which cell type is specialized for most of the alveolar gas-exchange surface?',options:['Type I pneumocyte','Type II pneumocyte','Goblet cell','Chondrocyte'],correct:0,why:'Type I pneumocytes form the thin epithelial surface specialized for gas exchange.'},
  {q:'Which alveolar cell produces pulmonary surfactant?',options:['Type I pneumocyte','Type II pneumocyte','Fibroblast','Endothelial cell'],correct:1,why:'Type II pneumocytes synthesize and secrete pulmonary surfactant.'},
  {q:'Where are pulmonary capillaries found in relation to alveoli?',options:['Within alveolar septa','Inside the airway lumen','Only in the pleura','Inside cartilage'],correct:0,why:'Capillaries run within the thin alveolar septa, bringing blood close to the air space.'}
 ]}
};
let activeQuiz=null,activeQuizKey=null,quizIndex=0,quizScore=0,quizAnswered=false;
const quizChooser=document.getElementById('quizChooser'),quizRunner=document.getElementById('quizRunner');
function startQuiz(key){activeQuizKey=key;activeQuiz=quizSets[key];quizIndex=0;quizScore=0;quizAnswered=false;quizChooser.hidden=true;quizRunner.hidden=false;document.getElementById('quizTitle').textContent=activeQuiz.title;document.getElementById('quizBadge').textContent=activeQuiz.badge;document.getElementById('quizImage').src=activeQuiz.image;document.getElementById('quizImage').alt=activeQuiz.badge+' histology specimen';document.getElementById('quizImageLabel').textContent=activeQuiz.imageLabel;renderQuizQuestion();}
function renderQuizQuestion(){const item=activeQuiz.questions[quizIndex];quizAnswered=false;document.getElementById('quizProgress').textContent=`Question ${quizIndex+1} of ${activeQuiz.questions.length}`;document.getElementById('quizScore').textContent=`${quizScore}/${quizIndex}`;document.getElementById('quizQuestionNumber').textContent=`Question ${quizIndex+1}`;document.getElementById('quizQuestion').textContent=item.q;const box=document.getElementById('quizOptions');box.innerHTML='';item.options.forEach((opt,i)=>{const b=document.createElement('button');b.type='button';b.className='quiz-option';b.textContent=String.fromCharCode(65+i)+'  '+opt;b.addEventListener('click',()=>answerQuiz(i));box.appendChild(b);});const f=document.getElementById('quizFeedback');f.className='quiz-feedback';f.textContent='Choose an answer to receive immediate feedback.';const next=document.getElementById('nextQuestion');next.disabled=true;next.textContent=quizIndex===activeQuiz.questions.length-1?'Finish Quiz →':'Next Question →';}
function answerQuiz(choice){if(quizAnswered)return;quizAnswered=true;const item=activeQuiz.questions[quizIndex];const correct=choice===item.correct;if(correct)quizScore++;document.querySelectorAll('#quizOptions .quiz-option').forEach((b,i)=>{b.disabled=true;if(i===item.correct)b.classList.add('correct');else if(i===choice)b.classList.add('incorrect');});const f=document.getElementById('quizFeedback');f.className='quiz-feedback '+(correct?'correct':'incorrect');f.innerHTML=`<b>${correct?'Correct!':'Not quite.'}</b> ${item.why}`;document.getElementById('quizScore').textContent=`${quizScore}/${quizIndex+1}`;document.getElementById('nextQuestion').disabled=false;}
function saveQuizProgress() {
  try {
    const raw = localStorage.getItem('westernHistologyQuizProgress');
    const entries = raw ? JSON.parse(raw) : [];
    entries.unshift({
      quiz: activeQuizKey,
      badge: activeQuiz.badge,
      score: quizScore,
      total: activeQuiz.questions.length,
      percent: Math.round((quizScore / activeQuiz.questions.length) * 100),
      completedAt: new Date().toISOString()
    });
    localStorage.setItem('westernHistologyQuizProgress', JSON.stringify(entries.slice(0, 10)));
  } catch (e) {
    // Local progress is optional; the quiz remains usable if browser storage is unavailable.
  }
  renderLearningProgress();
}
function renderLearningProgress() {
  const target = document.getElementById('progressSummary');
  if (!target) return;
  try {
    const raw = localStorage.getItem('westernHistologyQuizProgress');
    const entries = raw ? JSON.parse(raw) : [];
    if (!entries.length) {
      target.textContent = 'No quiz attempts saved on this device yet.';
      return;
    }
    const latest = entries[0];
    target.textContent = latest.badge + ' · ' + latest.score + '/' + latest.total + ' (' + latest.percent + '%) · ' + entries.length + ' saved attempt' + (entries.length === 1 ? '' : 's') + '.';
  } catch (e) {
    target.textContent = 'Local progress is unavailable in this browser.';
  }
}
function finishQuiz(){saveQuizProgress();const runner=document.getElementById('quizRunner');runner.innerHTML=`<div class="quiz-question-card" style="max-width:760px;margin:20px auto"><span class="badge">${activeQuiz.badge}</span><h2 style="font:700 32px Georgia;margin:8px 0">Quiz complete</h2><p style="color:var(--muted);font-size:17px">You scored <strong>${quizScore} / ${activeQuiz.questions.length}</strong>.</p><div class="quiz-complete">Review the slide in the Slide Box, then try the quiz again to reinforce the key structures.</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:18px"><button type="button" class="start-quiz" id="retryQuiz" style="width:auto">Try Again</button><button type="button" class="quiz-back" id="backFromComplete" style="padding:12px 4px">← All Quizzes</button></div></div>`;document.getElementById('retryQuiz').addEventListener('click',()=>{quizRunner.hidden=false;quizIndex=0;quizScore=0;renderQuizQuestion();});document.getElementById('backFromComplete').addEventListener('click',backToQuizHub);}
function clearLocalQuizProgress() {
  try { localStorage.removeItem('westernHistologyQuizProgress'); } catch (e) {}
  renderLearningProgress();
}
function backToQuizHub(){quizRunner.hidden=true;quizChooser.hidden=false;activeQuiz=null;activeQuizKey=null;renderLearningProgress();}
document.querySelectorAll('.start-quiz[data-quiz]').forEach(b=>b.addEventListener('click',()=>startQuiz(b.dataset.quiz)));document.getElementById('clearLocalProgress')?.addEventListener('click', clearLocalQuizProgress);
renderLearningProgress();quizRunner.addEventListener('click',e=>{if(e.target.id==='nextQuestion'){if(quizIndex===activeQuiz.questions.length-1)finishQuiz();else{quizIndex++;renderQuizQuestion();}}});document.getElementById('quizBack')?.addEventListener('click',backToQuizHub);

// Initial state and keyboard accessibility.
systemCards.forEach(card => {
  card.setAttribute('tabindex', '0');
  card.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      card.click();
    }
  });
});


(function(){
  function routeHash(){
    const id=(location.hash||'#home').slice(1);
    const target=document.getElementById(id) || document.getElementById('home');
    document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
    target.classList.add('active');
    document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active', b.dataset.page===id));
    window.scrollTo(0,0);
  }
  window.addEventListener('hashchange', routeHash);
  window.addEventListener('DOMContentLoaded', routeHash);
})();
